import Foundation
import SwiftUI
public struct JIAPracticeEvidence:Sendable,Equatable{public let id:String;public let lastReviewedAt:Date?;public let correctStreak:Int;public let recentWrong:Int;public let confidencePercent:Int;public init(id:String,lastReviewedAt:Date?,correctStreak:Int,recentWrong:Int,confidencePercent:Int){self.id=id;self.lastReviewedAt=lastReviewedAt;self.correctStreak=correctStreak;self.recentWrong=recentWrong;self.confidencePercent=confidencePercent}}
public struct JIAPracticeQueueItem:Identifiable,Sendable,Equatable{public let id:String;public let dueAt:Date;public let intervalDays:Int;public let priority:Int;public let rationale:String}
public enum JIAPracticeQueuePolicy{
 public static func intervalDays(streak:Int,wrong:Int,confidence:Int)->Int{let c=min(100,max(0,confidence));if wrong>0||c<50||streak<=0{return 1};if c<75||streak==1{return 2};if streak==2{return 4};return min(30,4*(1+min(6,streak-2)))}
 public static func due(_ evidence:[JIAPracticeEvidence],now:Date,limit:Int=30)->[JIAPracticeQueueItem]{precondition((1...100).contains(limit))
  return evidence.compactMap{e->JIAPracticeQueueItem? in guard !e.id.isEmpty,let last=e.lastReviewedAt else{return nil};let days=intervalDays(streak:e.correctStreak,wrong:e.recentWrong,confidence:e.confidencePercent);let due=last.addingTimeInterval(Double(days)*86400);guard due<=now else{return nil};let priority=min(100,50+max(0,e.recentWrong)*10+(100-min(100,max(0,e.confidencePercent)))/2);return JIAPracticeQueueItem(id:e.id,dueAt:due,intervalDays:days,priority:priority,rationale:e.recentWrong>0 ? "Review a missed concept":"Scheduled recall")}
  }.sorted{if $0.priority != $1.priority{return $0.priority>$1.priority};if $0.dueAt != $1.dueAt{return $0.dueAt<$1.dueAt};return $0.id<$1.id}.prefix(limit).map{$0}
 }
}
public struct JIAPracticeQueueView:View{public let items:[JIAPracticeQueueItem];public init(items:[JIAPracticeQueueItem]){self.items=items};public var body:some View{List{Section("Review queue · \(items.count) due"){if items.isEmpty{ContentUnavailableView("You're caught up",systemImage:"checkmark.circle",description:Text("Reviews return when evidence is due."))};ForEach(items){item in VStack(alignment:.leading,spacing:5){Text(item.id).font(.headline);Text("Priority \(item.priority) · interval \(item.intervalDays)d").font(.caption).foregroundStyle(.secondary);Text(item.rationale).font(.subheadline)}.padding(.vertical,4)}}}.navigationTitle("Practice queue")}}
